create extension if not exists pgcrypto;
create type listing_source as enum ('manual', 'reddit', 'ebay', 'facebook', 'other');
create type negotiation_state as enum ('discovered', 'valued', 'qualify_seller', 'ask_missing_questions', 'opening_offer', 'counter', 'economically_acceptable', 'pending_human_approval', 'agreed', 'rejected');
create table watch_references (id uuid primary key default gen_random_uuid(), brand text not null, model text not null, reference text not null unique, year_start smallint, year_end smallint, default_configuration jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table owned_assets (id uuid primary key default gen_random_uuid(), watch_reference_id uuid not null references watch_references(id), configuration jsonb not null default '{}'::jsonb, acquired_cost_cents integer, status text not null default 'owned', created_at timestamptz not null default now());
create table source_listings (id uuid primary key default gen_random_uuid(), source listing_source not null, source_key text, url text, raw_text text, seller_handle text, first_seen_at timestamptz not null default now(), unique(source, source_key));
create table listing_snapshots (id uuid primary key default gen_random_uuid(), listing_id uuid not null references source_listings(id), ask_cents integer, raw_payload jsonb not null default '{}'::jsonb, observed_at timestamptz not null default now());
create table listing_watch_candidates (id uuid primary key default gen_random_uuid(), listing_id uuid not null references source_listings(id), watch_reference_id uuid references watch_references(id), confidence numeric(5,4) not null, evidence jsonb not null default '[]'::jsonb, contradictions jsonb not null default '[]'::jsonb, selected_by_human boolean not null default false);
create table valuation_estimates (id uuid primary key default gen_random_uuid(), watch_reference_id uuid not null references watch_references(id), subject_listing_id uuid references source_listings(id), policy_version text not null, dealer_ask_cents integer, private_ask_cents integer, estimated_sale_cents integer, qlv_p10_cents integer not null, qlv_p50_cents integer not null, qlv_p90_cents integer not null, estimated_liquidation_days integer, inputs jsonb not null, created_at timestamptz not null default now());
create table risk_assessments (id uuid primary key default gen_random_uuid(), listing_id uuid not null references source_listings(id), policy_version text not null, expected_loss_cents integer not null, factors jsonb not null, created_at timestamptz not null default now());
create table opportunities (id uuid primary key default gen_random_uuid(), listing_id uuid not null references source_listings(id), offered_asset_id uuid not null references owned_assets(id), received_qlv_cents integer not null, given_qlv_cents integer not null, cash_paid_cents integer not null default 0, cash_received_cents integer not null default 0, cost_cents integer not null default 0, expected_risk_loss_cents integer not null default 0, liquidity_adjustment_cents integer not null default 0, economic_alpha_cents integer generated always as (received_qlv_cents + cash_received_cents - given_qlv_cents - cash_paid_cents - cost_cents - expected_risk_loss_cents) stored, created_at timestamptz not null default now());
create table negotiations (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references opportunities(id), state negotiation_state not null default 'discovered', minimum_alpha_cents integer not null, preferred_alpha_cents integer not null, max_cash_paid_cents integer not null, human_approval_required boolean not null default true, constraint human_approval_is_mandatory check (human_approval_required = true), updated_at timestamptz not null default now());
create table negotiation_events (id uuid primary key default gen_random_uuid(), negotiation_id uuid not null references negotiations(id), actor text not null check (actor in ('system', 'agent', 'human', 'counterparty')), event_type text not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index on listing_snapshots(listing_id, observed_at desc);
create index on valuation_estimates(watch_reference_id, created_at desc);
create index on negotiation_events(negotiation_id, created_at);
